package com.bananalab.lite;
import java.lang.reflect.*;import java.util.*;import org.json.*;
/** Evaluator uses generated inputs and a separate collection-based reference. */
final class ProgramJudge{
 static String[] samples(ProgramPlan plan,long seed){boolean formula=false;for(int k=0;k<plan.steps.length();k++)if(plan.steps.optJSONObject(k).optString("op").endsWith("_expr"))formula=true;Random r=new Random(seed);String[] out=new String[64];for(int i=0;i<out.length;i++){if(plan.family.equals("array")){if(i==0){out[i]="";continue;}if(i==1){out[i]="1000,-1000,0,1,1";continue;}if(i==2){out[i]="no-es-lista";continue;}int size=r.nextInt(18);StringBuilder s=new StringBuilder();for(int j=0;j<size;j++){if(j>0)s.append(',');s.append(formula&&i<32?r.nextInt(7)-3:r.nextInt(31)-15);}out[i]=s.toString();}else{if(i==0){out[i]="";continue;}if(i==1){out[i]="  Ñandú3 AbB!\t ";continue;}if(i==2){char[] a=new char[129];Arrays.fill(a,'x');out[i]=new String(a);continue;}String alphabet=" aBñÉ09!?\t";StringBuilder s=new StringBuilder();for(int j=r.nextInt(35);j>0;j--)s.append(alphabet.charAt(r.nextInt(alphabet.length())));out[i]=s.toString();}}return out;}
 static JSONObject check(Method method,ProgramPlan plan,long seed)throws Exception{int valid=0,invalid=0;String[] inputs=samples(plan,seed);for(String input:inputs){String expected=null,got=null;boolean bad=false,threw=false;try{expected=plan.oracle(input);}catch(IllegalArgumentException rejected){bad=true;}try{got=(String)method.invoke(null,new String(input));}catch(InvocationTargetException e){if(!(e.getCause() instanceof IllegalArgumentException))throw new IllegalArgumentException("Excepción no prevista del candidato.",e);threw=true;}if(bad!=threw||!bad&&!Objects.equals(expected,got))throw new IllegalArgumentException("El programa falló el evaluador, caso"+(valid+invalid+1)+".");if(bad)invalid++;else valid++;}if(valid<8||invalid<1)throw new IllegalArgumentException("Cobertura insuficiente.");return new JSONObject().put("passed",inputs.length).put("valid",valid).put("invalid",invalid).put("seed",seed).put("source","generated_contract_cases");}
}
